import axios from 'axios';

const API_KEY = '8c247ea0b4b56ed2ff7d41c9a833aa77';
const BASE_URL = 'https://api.themoviedb.org/3';

const tmdbService = {
  getContentDetails: async (id, type = 'movie') => {
    try {
      console.log(`Fetching ${type} details for ID: ${id}`);
      const response = await axios.get(`${BASE_URL}/${type}/${id}`, {
        params: {
          api_key: API_KEY,
          language: 'en-US',
          append_to_response: 'videos,credits,similar,recommendations'
        }
      });
      
      if (!response.data) {
        throw new Error('No data received from TMDB API');
      }
      
      return response.data;
    } catch (error) {
      console.error('Error fetching content details:', {
        id,
        type,
        status: error.response?.status,
        message: error.response?.data?.status_message || error.message
      });
      
      if (error.response?.status === 404) {
        throw new Error(`Movie with ID ${id} not found`);
      }
      
      throw new Error('Failed to fetch movie details. Please try again later.');
    }
  },

  searchContent: async (query, type = 'multi', page = 1) => {
    try {
      const response = await axios.get(`${BASE_URL}/search/${type}`, {
        params: {
          api_key: API_KEY,
          language: 'en-US',
          query,
          page
        }
      });
      return response.data;
    } catch (error) {
      console.error('Error searching content:', error);
      throw error;
    }
  },

  getPopular: async (type = 'movie', page = 1) => {
    try {
      const response = await axios.get(`${BASE_URL}/${type}/popular`, {
        params: {
          api_key: API_KEY,
          language: 'en-US',
          page
        }
      });
      return response.data;
    } catch (error) {
      console.error('Error fetching popular content:', error);
      throw error;
    }
  },

  getTopRated: async (type = 'movie', page = 1) => {
    try {
      const response = await axios.get(`${BASE_URL}/${type}/top_rated`, {
        params: {
          api_key: API_KEY,
          language: 'en-US',
          page
        }
      });
      return response.data;
    } catch (error) {
      console.error('Error fetching top rated content:', error);
      throw error;
    }
  },

  getUpcoming: async (page = 1) => {
    try {
      const response = await axios.get(`${BASE_URL}/movie/upcoming`, {
        params: {
          api_key: API_KEY,
          language: 'en-US',
          page
        }
      });
      return response.data;
    } catch (error) {
      console.error('Error fetching upcoming movies:', error);
      throw error;
    }
  },

  getGenres: async (type = 'movie') => {
    try {
      const response = await axios.get(`${BASE_URL}/genre/${type}/list`, {
        params: {
          api_key: API_KEY,
          language: 'en-US'
        }
      });
      return response.data;
    } catch (error) {
      console.error('Error fetching genres:', error);
      throw error;
    }
  },

  getRecommendations: async (id, type = 'movie', page = 1) => {
    try {
      const response = await axios.get(`${BASE_URL}/${type}/${id}/recommendations`, {
        params: {
          api_key: API_KEY,
          language: 'en-US',
          page
        }
      });
      return response.data;
    } catch (error) {
      console.error('Error fetching recommendations:', error);
      throw error;
    }
  },

  getSimilar: async (id, type = 'movie', page = 1) => {
    try {
      const response = await axios.get(`${BASE_URL}/${type}/${id}/similar`, {
        params: {
          api_key: API_KEY,
          language: 'en-US',
          page
        }
      });
      return response.data;
    } catch (error) {
      console.error('Error fetching similar content:', error);
      throw error;
    }
  }
};

export default tmdbService;
